    { id:'N07', question:'Are alternate navigation paths available when needed?', navigate:'Look for search functionality, secondary menus, in-page anchor links, and keyboard shortcuts. Test each one that exists.', options:[{mark:1,text:'Missing or ineffective — no secondary navigation, search, or shortcuts anywhere'},{mark:2,text:'Very limited — only one alternative path and it is hard to find'},{mark:3,text:'Available but limited — search or secondary links present but incomplete'},{mark:4,text:'Available and mostly useful — secondary paths work but could be better'},{mark:5,text:'Clearly available and useful — search, secondary menus, shortcuts all present'}] },
    { id:'N08', question:'Can the user reach the core action in 3 clicks or fewer from the homepage?', navigate:'Start from the homepage. Navigate to the most important action. Count every click.', options:[{mark:1,text:'Requires 7 or more clicks — core action is effectively buried'},{mark:2,text:'Requires 5 to 6 clicks — significant navigation depth'},{mark:3,text:'Requires 4 clicks — one more step than ideal'},{mark:4,text:'Requires 3 clicks — acceptable with minor friction'},{mark:5,text:'Reached in 1 to 2 clicks — immediately accessible from entry screen'}] },
    { id:'N09', question:'Is the back navigation predictable and reliable?', navigate:'Navigate deep into the product then use the back button. Check whether the result is what is expected.', options:[{mark:1,text:'Back navigation is broken or absent — users get stuck or lose progress'},{mark:2,text:'Back navigation works but loses user data or resets state unexpectedly'},{mark:3,text:'Back navigation works but redirects to unexpected screens occasionally'},{mark:4,text:'Back navigation works reliably with one minor unexpected behaviour'},{mark:5,text:'Back navigation is fully predictable — works correctly in every flow'}] },
    { id:'N10', question:'Are key user flows friction-free with no dead ends or broken links?', navigate:'Navigate every flow listed in the audit scope from start to finish. Note every broken link, dead end, or unexpected redirect.', options:[{mark:1,text:'Multiple dead ends, broken links, or failed flows found across the product'},{mark:2,text:'2 or 3 significant friction points or broken steps found'},{mark:3,text:'1 friction point found — one step in a flow that causes confusion'},{mark:4,text:'Flows are mostly smooth with very minor friction in one place'},{mark:5,text:'All flows complete seamlessly — no dead ends, broken links, or unexpected stops'}] }
