    { id:'W02', question:'Are CTA button labels outcome-oriented and specific?', navigate:'Read every CTA button across the homepage, core feature screen, and conversion screen. Classify each as outcome-oriented or generic.', options:[{mark:1,text:'All CTAs are generic — Submit, Click here, Go, or Learn more throughout'},{mark:2,text:'Most CTAs are generic — only 1 or 2 are specific across the product'},{mark:3,text:'Mix of specific and generic — approximately half are outcome-oriented'},{mark:4,text:'Most CTAs are specific — 1 generic CTA found on a secondary screen'},{mark:5,text:'All CTAs describe the outcome — every button tells the user what happens next'}] },
    { id:'W03', question:'Is terminology consistent across all screens?', navigate:'Navigate 6 screens and note what key features and actions are called on each. Look for the same concept being named differently.', options:[{mark:1,text:'Same features called completely different names on different screens'},{mark:2,text:'3 or more terminology inconsistencies found across the product'},{mark:3,text:'1 or 2 inconsistencies — same feature referred to differently in places'},{mark:4,text:'Mostly consistent with one minor terminology variation'},{mark:5,text:'Fully consistent — same words used for same things everywhere throughout'}] },
    { id:'W04', question:'Are error messages written in plain language with a specific actionable fix?', navigate:'Trigger at least 3 errors — submit an empty required form, enter invalid credentials, attempt an unauthorised action. Read every error message.', options:[{mark:1,text:'Technical error codes or completely generic errors — no fix provided'},{mark:2,text:'Errors show what went wrong but the fix is completely absent'},{mark:3,text:'Errors state the problem in plain language but the fix is vague'},{mark:4,text:'Errors are clear and mostly actionable with minor improvements needed'},{mark:5,text:'All errors are plain language with specific problem and specific fix stated'}] },
    { id:'W05', question:'Is helper text, microcopy, or tooltips present at key decision points?', navigate:'Navigate to the most complex form, the onboarding flow, and the checkout or upgrade flow. Look for helper text, tooltips, placeholder guidance, and inline hints.', options:[{mark:1,text:'No microcopy anywhere — users are left to guess throughout the entire product'},{mark:2,text:'Microcopy present in only 1 place — all other decision points have no guidance'},{mark:3,text:'Present at some decision points but missing at the most critical ones'},{mark:4,text:'Present at most decision points with one or two gaps'},{mark:5,text:'Guidance present at every key decision point throughout the product'}] },
    { id:'W06', question:'Is content structured for scanning with headings, short paragraphs, and emphasis?', navigate:'Open any content-heavy screen. Check whether content is skimmable without reading every word.', options:[{mark:1,text:'Wall of text throughout — no headings, no structure, no visual emphasis'},{mark:2,text:'Very little structure — long paragraphs with minimal formatting'},{mark:3,text:'Some structure present — headings exist but large text blocks remain'},{mark:4,text:'Mostly scannable — minor areas where long text blocks appear'},{mark:5,text:'Fully scannable — headings, short paragraphs, and clear emphasis throughout'}] },
    { id:'W07', question:'Are success and confirmation messages specific with next steps indicated?', navigate:'Complete 3 different primary actions. Read the confirmation message that appears after each action.', options:[{mark:1,text:'No confirmation messages — users have no idea if their action succeeded'},{mark:2,text:'Generic silent state change only — action appears to complete but nothing is said'},{mark:3,text:'Generic confirmation shown — Done or Success with no next step'},{mark:4,text:'Specific confirmation present but next step is not indicated'},{mark:5,text:'Specific confirmation with clear next step on every completed action'}] },
    { id:'W08', question:'Is all copy free of jargon, filler phrases, and redundant text?', navigate:'Read all copy on 4 key screens. Count instances of jargon, buzzwords, filler phrases, and redundant repetition.', options:[{mark:1,text:'Heavy jargon and buzzwords throughout — inaccessible to non-expert users'},{mark:2,text:'Significant jargon present — multiple screens have inaccessible copy'},{mark:3,text:'Some jargon present — 3 or more instances across the product'},{mark:4,text:'Mostly clear — 1 or 2 instances of jargon or unnecessary filler'},{mark:5,text:'No jargon or filler — every word is necessary and plain throughout'}] },
    { id:'W09', question:'Is the value proposition communicated consistently across all key screens?', navigate:'Read the core message on the homepage, a feature page, and the pricing or upgrade screen. Check whether the same positioning is consistently communicated.', options:[{mark:1,text:'No consistent value proposition — each screen communicates something different'},{mark:2,text:'Value proposition only on homepage — completely absent on other screens'},{mark:3,text:'Present on 2 screens but inconsistent or contradictory in places'},{mark:4,text:'Consistent on most screens — one screen feels off-message'},{mark:5,text:'Same clear positioning consistently communicated on every key screen'}] },
    { id:'W10', question:'Does microcopy guide users through complex workflows and multi-step processes?', navigate:'Navigate the longest multi-step flow in the product. Check for guidance at every step.', options:[{mark:1,text:'No guidance in any workflow — users must figure out every step alone'},{mark:2,text:'Guidance appears only at the first step — subsequent steps have no help'},{mark:3,text:'Guidance at entry and exit only — middle steps have no microcopy'},{mark:4,text:'Guidance at most steps — one critical mid-flow step lacks explanation'},{mark:5,text:'Comprehensive microcopy at every step of every complex workflow'}] }
