    { id:'V06', question:'Is visual noise minimised with no distracting elements competing with the primary action?', navigate:'Scan 3 screens for decorative elements, competing banners, or repeated CTAs that distract from the primary action.', options:[{mark:1,text:'Heavy visual noise — multiple banners and competing CTAs clutter every screen'},{mark:2,text:'Significant noise on most screens — primary action is regularly obscured'},{mark:3,text:'Noise present on 2 or 3 screens — distracting from the primary action'},{mark:4,text:'Mostly clean — one minor distracting element on one screen'},{mark:5,text:'No visual noise — every element serves a purpose and primary action is unobstructed'}] },
    { id:'V07', question:'Does the layout adapt correctly across desktop, tablet, and mobile breakpoints?', navigate:'Test the primary flow at 1280px desktop, 768px tablet, and 375px mobile. Check for overflow, broken layouts, or cut-off content.', options:[{mark:1,text:'Layout is completely broken on mobile — horizontal scroll and overlapping elements'},{mark:2,text:'Significant layout issues on mobile — unusable on small screens'},{mark:3,text:'Minor layout issues on one breakpoint — small element or spacing problem'},{mark:4,text:'Layout mostly adapts — one minor reflow issue on tablet or mobile'},{mark:5,text:'Perfect reflow at all breakpoints — no layout issues at any screen size'}] },
    { id:'V08', question:'Are related elements visually grouped using proximity, borders, or background?', navigate:'Check any form, feature section, or content block. Verify that related elements are grouped by proximity or visual cues.', options:[{mark:1,text:'No grouping — all elements appear scattered across the screen with no visual logic'},{mark:2,text:'Very weak grouping — most related elements are not visually connected'},{mark:3,text:'Some grouping — 2 or 3 content sections where related elements are not grouped'},{mark:4,text:'Mostly grouped — one section where related elements are slightly scattered'},{mark:5,text:'All related elements clearly grouped — proximity and visual cues used throughout'}] },
    { id:'V09', question:'Is the layout guiding the eye flow from headline through content to the CTA?', navigate:'On the homepage and conversion screen, trace the visual path from the headline down the page toward the primary CTA.', options:[{mark:1,text:'Eye flow is completely random — no logical sequence from entry to CTA'},{mark:2,text:'Eye flow breaks significantly at the midpoint — does not lead to CTA'},{mark:3,text:'Eye flow is mostly logical but breaks once before reaching the CTA'},{mark:4,text:'Eye flow leads to CTA but one element slightly disrupts the path'},{mark:5,text:'Eye flows naturally from headline through content directly to CTA on every screen'}] },
    { id:'V10', question:'Is visual weight balanced with no non-primary element accidentally dominating the screen?', navigate:'Check 3 screens for any element that dominates unintentionally — large background image, bright secondary badge, or oversized secondary CTA.', options:[{mark:1,text:'Multiple non-primary elements dominate — primary action is visually lost'},{mark:2,text:'One non-primary element dominates most screens accidentally'},{mark:3,text:'One screen where a secondary element accidentally competes with the primary'},{mark:4,text:'Balance is mostly correct — one minor element slightly heavier than intended'},{mark:5,text:'Perfectly balanced — primary elements dominate intentionally on every screen'}] }
