    { id:'A02', question:'Can a keyboard-only user navigate and operate the full primary flow without a mouse?', navigate:'Use the Tab key only to navigate the complete primary flow. Press Enter or Space to activate elements.', options:[{mark:1,text:'Keyboard navigation is completely broken — primary flow cannot be completed'},{mark:2,text:'Keyboard navigation works for less than half the primary flow'},{mark:3,text:'Keyboard navigation works for most of the flow but 2 elements are unreachable'},{mark:4,text:'Keyboard navigation works throughout with one minor focus trap or skip'},{mark:5,text:'Full keyboard navigation works perfectly — entire primary flow operable without mouse'}] },
    { id:'A03', question:'Are focus states visible on all interactive elements when tabbing through the page?', navigate:'Tab through any full page. Observe whether each focusable element shows a visible focus ring or highlight.', options:[{mark:1,text:'No visible focus states anywhere — keyboard users cannot track their position'},{mark:2,text:'Focus states present on less than half of interactive elements'},{mark:3,text:'Focus states present on most elements but missing on several links or inputs'},{mark:4,text:'Focus states present on almost all elements — missing on one secondary component'},{mark:5,text:'Visible focus state on every interactive element — clearly distinguishable throughout'}] },
    { id:'A04', question:'Do all form fields have persistent visible labels — not just placeholder text?', navigate:'Navigate to any form. Click into each field and begin typing. Check whether the label remains visible above or beside the field.', options:[{mark:1,text:'All fields use placeholder text only — all labels disappear on typing'},{mark:2,text:'Most fields use placeholder only — fewer than 2 have persistent labels'},{mark:3,text:'Mix of persistent labels and placeholder-only fields across the form'},{mark:4,text:'Most fields have persistent labels — one field uses placeholder text only'},{mark:5,text:'All fields have persistent visible labels — no labels disappear when typing begins'}] },
    { id:'A05', question:'Are all tap and click targets at least 44 x 44 pixels on mobile?', navigate:'Set viewport to 375px. Visually inspect all interactive elements — buttons, icon buttons, navigation links, toggles, and checkboxes.', options:[{mark:1,text:'Most targets are below 44px — buttons, icons, and links are all too small on mobile'},{mark:2,text:'Multiple targets below 44px — icon buttons and navigation links are too small'},{mark:3,text:'2 or 3 targets below 44px — mostly icon buttons or close buttons'},{mark:4,text:'1 target slightly below 44px — a minor icon or secondary link'},{mark:5,text:'All tap and click targets meet or exceed 44px on mobile — fully accessible'}] },
    { id:'A06', question:'Are errors and status indicators communicated through more than just colour?', navigate:'Trigger a form error. Observe the error indicator. Check whether it uses only colour or also includes an icon or text label.', options:[{mark:1,text:'Errors communicated through colour only — no icon, pattern, or label added'},{mark:2,text:'Most error indicators are colour-only — text label present in only one case'},{mark:3,text:'Some errors use colour plus text — others use colour only'},{mark:4,text:'Most errors use colour plus icon — one error uses colour only'},{mark:5,text:'All errors use colour plus icon plus text label — three independent signals'}] },
    { id:'A07', question:'Does the layout remain usable and readable when browser zoom is set to 200%?', navigate:'Set browser zoom to 200% on the homepage and core feature screen. Check for horizontal scroll, overlapping elements, or cut-off content.', options:[{mark:1,text:'Layout completely breaks at 200% — horizontal scroll and overlapping content'},{mark:2,text:'Significant layout issues at 200% — content is cut off on multiple screens'},{mark:3,text:'Minor layout issue at 200% — one element slightly cut off or overlapping'},{mark:4,text:'Mostly usable at 200% — one small spacing issue found'},{mark:5,text:'Fully usable at 200% zoom — no horizontal scroll or overlapping elements'}] },
    { id:'A08', question:'Are images and meaningful visual elements accompanied by descriptive alt text?', navigate:'Inspect the HTML of images on 3 key screens. Check whether meaningful images have descriptive alt text.', options:[{mark:1,text:'No alt text on any images — all are completely inaccessible to screen readers'},{mark:2,text:'Alt text present on fewer than half of meaningful images'},{mark:3,text:'Alt text present on most images — 2 or 3 meaningful images are missing it'},{mark:4,text:'Almost all images have alt text — one meaningful image is missing it'},{mark:5,text:'All meaningful images have descriptive alt text — decorative images have empty alt'}] },
    { id:'A09', question:'Is animation and motion controlled and non-disruptive?', navigate:'Observe all animations and transitions. Enable OS reduced-motion setting and reload to check whether animations are suppressed.', options:[{mark:1,text:'Heavy animation throughout — no reduced-motion support and some elements flash'},{mark:2,text:'Significant animation with no reduced-motion support at all'},{mark:3,text:'Animation present with partial reduced-motion support — some animations persist'},{mark:4,text:'Animation is subtle with mostly correct reduced-motion support'},{mark:5,text:'Animations are subtle, respect reduced-motion preference, and no elements flash'}] },
    { id:'A10', question:'Is all content understandable at a broad reading level without expert knowledge?', navigate:'Read the copy on the homepage, onboarding flow, and error messages as if you are a non-expert user.', options:[{mark:1,text:'Heavy jargon and technical language throughout — inaccessible to general users'},{mark:2,text:'Significant technical language — non-expert users would struggle on most screens'},{mark:3,text:'Some technical language on 2 or 3 screens — partially inaccessible'},{mark:4,text:'Mostly accessible — one area where language is slightly technical'},{mark:5,text:'Plain language throughout — accessible to users of all literacy levels'}] }
